mapper.select:
select
FROM REP_TRADE R LEFT JOIN FIN_PRODUCT_ADD A ON A.PROD_REGIST_CODE = R.REP_FINPROD_REG_ID LEFT JOIN FIN_PRODUCT F ON A.FINPROD_ID = F.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY M ON R.REP_TRADE_COMPONENT = M.COUNTER_ID
AND (F.FINPROD_MARKET_ID IN
null) or F.FINPROD_MARKET_ID in (
#{item}
)
AND (R.REP_FINPROD_REG_ID IN
null) OR R.REP_FINPROD_REG_ID IN (
#{item}
)
AND R.REP_BANK_ASSET_CODE = #{repBankAssetCode}
AND R.REP_BANK_TRADE_CODE = #{repBankTradeCode}
AND R.REP_TRADE_DATE BETWEEN STR_TO_DATE(#{repTradeDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{repTradeDateEnd},'%Y-%m-%d')
AND R.REP_STATUS_DATE BETWEEN STR_TO_DATE(#{repStatusDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{repStatusDateEnd},'%Y-%m-%d')
AND (CONCAT_WS('',R.REP_BANK_TRADE_CODE,'_',R.REP_MONEY_FLOW_TYPE) IN
null) OR CONCAT_WS('',R.REP_BANK_TRADE_CODE,'_',R.REP_MONEY_FLOW_TYPE) in (
#{item}
)
AND R.REP_SEND_STATUS = #{repSendStatus}
